from fastapi import APIRouter, Depends, HTTPException, statusfrom fastapi.security import OAuth2PasswordRequestFormfrom sqlalchemy.orm import Sessionfrom .. import crud, auth, database, schemas, configrouter = APIRouter(prefix="/auth", tags=["auth"])settings = config.settings@router.post("/token", response_model=schemas.Token)def login_for_access_token(form_data: OAuth2PasswordRequestForm = Depends(), db: Session = Depends(database.get_db)):    user = crud.get_user_by_username(db, form_data.username)    if not user or not auth.verify_password(form_data.password, user.hashed_password):        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail="Incorrect username or password")    access_token = auth.create_access_token({"sub": user.username})    return {"access_token": access_token, "token_type": "bearer"}